def F(n):
    if n == 0: return 0
    if n % 3 == 0:
        return F(n // 3)
    else:
        return 1 + F(n - 1)

count = 0
for n in range(1, 1001):
    if F(n) == 4:
        count += 1
print(count)

def f(n):
    if n == 0: return 0
    if n % 3 == 0: return f(n // 3)
    return 1 + f(n - 1)

out = []
for n in range(1, 1001):
    if f(n) == 4:
        out.append(n)
print(len(out))
